from pathlib import Path
import json
p=Path('content/isc2-cc-2026/sources/domain-5/production')
slots={s['id']:s for s in json.loads((p/'blueprint.json').read_text(encoding='utf-8'))}
items=[]
def add(id,en,th,choices,decision):
 s=slots[id].copy();s.update(stem=[en,th],choices=choices,correct=0,takeaway=choices[0][2],assessedDecision=decision,status='DRAFT');items.append(s)
add(1001,'A data owner assigns a report to the Restricted category. An analyst then adds a Restricted metadata tag to the file. Which statement correctly distinguishes these actions?','เจ้าของข้อมูลจัดรายงานเป็นประเภท Restricted จากนั้นนักวิเคราะห์เพิ่มป้าย Metadata ว่า Restricted ให้ไฟล์ ข้อใดแยกสองการกระทำนี้ได้ถูกต้อง?',[
['The owner classifies the data; the analyst labels it','เจ้าของจัดประเภทข้อมูล ส่วนนักวิเคราะห์ติดป้าย','Classification determines the category; labeling communicates the category already assigned.','Classification กำหนดประเภท ส่วน Labeling แสดงประเภทที่กำหนดไว้แล้ว'],
['The owner labels the data; the analyst classifies it','เจ้าของติดป้าย ส่วนนักวิเคราะห์จัดประเภท','This reverses assignment of the category and attachment of its indicator.','ข้อนี้สลับการกำหนดประเภทกับการติดตัวบ่งชี้ประเภท'],
['Both actions enforce the file’s access permissions','ทั้งสองการกระทำบังคับสิทธิ์เข้าถึงไฟล์','A category or tag can guide enforcement, but neither described action establishes permissions by itself.','ประเภทและป้ายอาจช่วยกำหนดการควบคุม แต่การกระทำที่ระบุไม่ได้ตั้งสิทธิ์โดยตัวมันเอง'],
['Both actions encrypt the contents of the report','ทั้งสองการกระทำเข้ารหัสเนื้อหารายงาน','Categorizing and tagging describe handling requirements; they do not transform content into ciphertext.','การจัดประเภทและติดป้ายสื่อข้อกำหนดการจัดการ ไม่ได้แปลงเนื้อหาเป็น Ciphertext']], 'Separate category assignment from category indication')
add(1002,'Policy defines Internal data as employee-only and Restricted data as accessible only to named project members. A draft contains both types, and policy requires mixed documents to follow the more restrictive category. How should the analyst handle the draft?','นโยบายกำหนดว่า Internal ใช้ได้เฉพาะพนักงาน ส่วน Restricted ใช้ได้เฉพาะสมาชิกโครงการที่ระบุชื่อ ร่างเอกสารมีทั้งสองประเภทและนโยบายให้ใช้ประเภทที่เข้มงวดกว่า นักวิเคราะห์ควรจัดการอย่างไร?',[
['Apply Restricted handling to the complete draft','ใช้ข้อกำหนด Restricted กับร่างทั้งหมด','The supplied mixed-document rule requires the more restrictive category for this draft.','กฎสำหรับเอกสารผสมที่ระบุให้ใช้ประเภทที่เข้มงวดกว่าสำหรับร่างนี้'],
['Apply Internal handling because both parts are corporate data','ใช้ข้อกำหนด Internal เพราะทั้งสองส่วนเป็นข้อมูลบริษัท','Employee-wide access would exceed the named-project restriction on part of the document.','การให้พนักงานทั่วไปเข้าถึงเกินขอบเขตสมาชิกโครงการที่กำหนดไว้ในข้อมูลบางส่วน'],
['Apply the category covering the larger portion of the draft','ใช้ประเภทของข้อมูลที่มีสัดส่วนมากกว่าในร่าง','The stated rule is based on the more restrictive content, not its proportion.','กฎที่ระบุพิจารณาเนื้อหาที่จำกัดกว่า ไม่ใช่สัดส่วนของเนื้อหา'],
['Apply separate labels while leaving the whole file employee-accessible','ติดป้ายแต่ละส่วนโดยให้พนักงานทั้งหมดเข้าถึงไฟล์ได้','Labels alone do not satisfy the document-wide handling rule or limit access.','ป้ายเพียงอย่างเดียวไม่ทำให้เป็นไปตามกฎจัดการทั้งเอกสารหรือจำกัดการเข้าถึง']], 'Apply an explicitly supplied mixed-classification rule')
add(1003,'A support screen replaces all but the last four digits of an account number with X characters. Staff can still identify the relevant account record. Which data-handling technique is illustrated?','หน้าจอฝ่ายสนับสนุนแทนเลขบัญชีทุกหลักยกเว้นสี่หลักท้ายด้วย X โดยพนักงานยังเลือกบันทึกบัญชีที่เกี่ยวข้องได้ ตัวอย่างนี้ใช้เทคนิคใด?',[
['Data masking','การปกปิดข้อมูลบางส่วน (Data masking)','Masking conceals selected values while retaining information needed for the support task.','Masking ปกปิดค่าบางส่วนโดยคงข้อมูลที่จำเป็นต่องานสนับสนุน'],
['Symmetric encryption','การเข้ารหัสแบบ Symmetric','Encryption would create keyed ciphertext; the described screen shows selected original digits instead.','Encryption สร้าง Ciphertext ด้วยกุญแจ แต่หน้าจอนี้แสดงหลักเดิมที่เลือกไว้'],
['Cryptographic hashing','การคำนวณ Cryptographic hash','A digest is derived from input; replacing selected digits with X is not digest computation.','Digest คำนวณจากข้อมูลนำเข้า การแทนบางหลักด้วย X ไม่ใช่การคำนวณ Digest'],
['Media sanitization','การทำ Media sanitization','Sanitization addresses recovery of target data from media, rather than limiting a screen display.','Sanitization จัดการการกู้ข้อมูลจากสื่อ ไม่ใช่เพียงจำกัดสิ่งที่แสดงบนหน้าจอ']], 'Recognize purpose-preserving concealment of displayed values')
add(1004,'An approved AI service may receive support examples only after all customer identifiers are removed. An analyst masks the customer-number column, but names remain in free-text comments. What should the analyst do before submission?','บริการ AI ที่อนุมัติรับตัวอย่างงานสนับสนุนได้หลังลบข้อมูลระบุตัวลูกค้าทั้งหมดแล้ว นักวิเคราะห์ปกปิดคอลัมน์เลขลูกค้า แต่ยังมีชื่อในความคิดเห็นแบบ Free text ควรทำอะไรก่อนส่ง?',[
['Review the comments and remove the remaining identifiers','ตรวจความคิดเห็นและลบข้อมูลระบุตัวที่ยังเหลือ','The rule covers all identifiers, including free text; masking one column does not meet it.','กฎครอบคลุมข้อมูลระบุตัวทั้งหมดรวม Free text การปกปิดคอลัมน์เดียวจึงยังไม่พอ'],
['Submit because the structured identifier column is masked','ส่งได้เพราะคอลัมน์ระบุตัวแบบมีโครงสร้างถูกปกปิดแล้ว','Names in comments still violate the stated condition for submitting examples.','ชื่อในความคิดเห็นยังละเมิดเงื่อนไขการส่งตัวอย่างที่ระบุ'],
['Encrypt the upload and leave the comments unchanged','เข้ารหัสการส่งโดยคงความคิดเห็นเดิม','Transport protection does not remove identifiers that the receiving service can read.','การป้องกันระหว่างส่งไม่ได้ลบข้อมูลระบุตัวที่บริการปลายทางอ่านได้'],
['Replace the customer numbers with stable codes and submit','แทนเลขลูกค้าด้วยรหัสคงที่แล้วส่ง','Changing the identifier column again does not address the remaining names in free text.','การแก้คอลัมน์เลขลูกค้าอีกครั้งไม่จัดการชื่อที่เหลือใน Free text']], 'Apply an explicit all-identifiers sharing constraint to unstructured data')
add(1005,'An SSD containing confidential files will be reused internally. Policy requires a validated purge method that preserves reuse. The device supports an approved sanitize operation. Which handling plan meets the requirement?','SSD ที่มีไฟล์ลับจะนำกลับมาใช้ภายใน นโยบายกำหนดให้ใช้วิธี Purge ที่ตรวจยืนยันประสิทธิผลและยังใช้สื่อซ้ำได้ อุปกรณ์รองรับคำสั่ง Sanitize ที่อนุมัติแล้ว แผนใดตรงข้อกำหนด?',[
['Run the approved operation and validate its recorded outcome','เรียกคำสั่งที่อนุมัติและตรวจยืนยันประสิทธิผลจากผลที่บันทึก','The supported purge operation and outcome validation address both sanitization and reuse requirements.','คำสั่ง Purge ที่รองรับพร้อมการตรวจผลตอบทั้งข้อกำหนด Sanitization และการใช้ซ้ำ'],
['Quick-format the drive and confirm the old folders are hidden','Quick format แล้วตรวจว่าไม่เห็นโฟลเดอร์เดิม','A missing directory listing does not establish the required purge of recoverable data.','การไม่เห็นรายการโฟลเดอร์ไม่ได้ยืนยันว่า Purge ข้อมูลที่กู้คืนได้ตามที่ต้องการ'],
['Delete the confidential files and perform a normal file search','ลบไฟล์ลับแล้วค้นหาไฟล์ตามปกติ','Ordinary deletion and search do not demonstrate that the required sanitization method completed.','การลบและค้นหาปกติไม่ได้พิสูจน์ว่าวิธี Sanitization ที่กำหนดเสร็จสมบูรณ์'],
['Physically destroy the storage chips and document destruction','ทำลายชิปเก็บข้อมูลและบันทึกการทำลาย','Destruction prevents the intended reuse, so it fails one of the stated requirements.','การทำลายทำให้ใช้สื่อซ้ำตามแผนไม่ได้ จึงไม่ตรงข้อกำหนดหนึ่งของโจทย์']], 'Select verified sanitization compatible with required reuse')
add(1006,'A drive was encrypted before sensitive data was stored. Its data-encryption key is removed from the drive, but a recoverable copy remains in an escrow system. Has cryptographic erase been established?','ไดรฟ์ถูกเข้ารหัสก่อนเก็บข้อมูลสำคัญ กุญแจเข้ารหัสข้อมูลถูกลบออกจากไดรฟ์ แต่ยังมีสำเนาที่กู้คืนได้ในระบบ Escrow ยืนยันว่าเกิด Cryptographic erase แล้วได้หรือไม่?',[
['No; the retained key copy can still enable decryption','ยังไม่ได้ เพราะสำเนากุญแจที่เก็บไว้ยังอาจถอดรหัสได้','Cryptographic erase must address recoverable copies of relevant keys; the escrow copy preserves a decryption path.','Cryptographic erase ต้องจัดการสำเนากุญแจที่เกี่ยวข้องซึ่งกู้คืนได้ สำเนา Escrow ยังเป็นช่องทางถอดรหัส'],
['Yes; removing the local key is sufficient for encrypted media','ได้ เพราะลบกุญแจในสื่อที่เข้ารหัสแล้วก็พอ','Local removal alone does not eliminate the recoverable escrowed copy.','การลบเฉพาะในไดรฟ์ไม่ได้กำจัดสำเนา Escrow ที่กู้คืนได้'],
['Yes; encryption before storage makes later key retention irrelevant','ได้ เพราะเข้ารหัสก่อนเก็บแล้วจึงไม่ต้องสนใจกุญแจที่เก็บไว้','Prior encryption is necessary context, but a surviving usable key can still recover plaintext.','การเข้ารหัสก่อนเก็บเป็นเงื่อนไขสำคัญ แต่กุญแจที่ยังใช้ได้อาจกู้ Plaintext ได้'],
['No; cryptographic erase requires destruction of the drive itself','ยังไม่ได้ เพราะ Cryptographic erase ต้องทำลายไดรฟ์ด้วย','Cryptographic erase depends on key sanitization, not a universal requirement to physically destroy the drive.','Cryptographic erase อาศัยการ Sanitization กุญแจ ไม่ได้บังคับให้ทำลายไดรฟ์ทางกายภาพเสมอ']], 'Evaluate surviving escrow keys rather than treating encryption as erasure')
add(1007,'A sender must encrypt a short message so only the intended recipient can decrypt it using a public-key encryption scheme. Which key should the sender use to encrypt the message?','ผู้ส่งต้องเข้ารหัสข้อความสั้นด้วย Public-key encryption เพื่อให้ผู้รับที่ตั้งใจไว้เท่านั้นถอดรหัสได้ ผู้ส่งควรใช้กุญแจใดเข้ารหัส?',[
['The recipient’s public encryption key','Public encryption key ของผู้รับ','The matching recipient private key performs decryption and remains protected by the recipient.','Private Key ที่สอดคล้องกันของผู้รับใช้ถอดรหัสและต้องได้รับการป้องกันโดยผู้รับ'],
['The sender’s private signing key','Private signing key ของผู้ส่ง','Signing supports verification of origin and integrity; it does not provide recipient-only message confidentiality.','การลงนามช่วยตรวจที่มาและ Integrity ไม่ได้ทำให้มีเพียงผู้รับเท่านั้นที่อ่านข้อความได้'],
['The sender’s public encryption key','Public encryption key ของผู้ส่ง','That key would protect content for the sender’s private key, rather than the intended recipient’s key.','กุญแจนี้ปกป้องข้อความสำหรับ Private Key ของผู้ส่ง แทนที่จะเป็นของผู้รับที่ตั้งใจไว้'],
['The recipient’s private decryption key','Private decryption key ของผู้รับ','The sender should not obtain the recipient’s secret private key to encrypt this message.','ผู้ส่งไม่ควรขอ Private Key ลับของผู้รับเพื่อเข้ารหัสข้อความนี้']], 'Distinguish recipient encryption from signing and private-key disclosure')
add(1008,'An analyst compares a downloaded file with a SHA-256 digest obtained through the publisher’s authenticated channel. The digests differ. Which conclusion is supported by this evidence alone?','นักวิเคราะห์เปรียบเทียบไฟล์ที่ดาวน์โหลดกับ SHA-256 digest ที่ได้รับผ่านช่องทางยืนยันตัวตนของผู้เผยแพร่ ค่า Digest ไม่ตรงกัน หลักฐานนี้เพียงอย่างเดียวสนับสนุนข้อสรุปใด?',[
['The downloaded file does not match the referenced content','ไฟล์ที่ดาวน์โหลดไม่ตรงกับเนื้อหาที่ใช้อ้างอิง','A trusted-reference mismatch establishes a content difference, but not its cause or the actor responsible.','ค่าที่ไม่ตรงกับแหล่งอ้างอิงที่เชื่อถือได้บอกว่าเนื้อหาต่างกัน แต่ยังไม่บอกสาเหตุหรือผู้กระทำ'],
['The file was deliberately modified by an external attacker','ผู้โจมตีภายนอกจงใจแก้ไขไฟล์','Mismatch alone does not distinguish malicious modification from corruption or a different version.','ค่าไม่ตรงกันอย่างเดียวแยกการแก้ไขโดยเจตนาร้ายออกจากความเสียหายหรือคนละเวอร์ชันไม่ได้'],
['The publisher’s private signing key has been compromised','Private signing key ของผู้เผยแพร่ถูกยึดครองแล้ว','The comparison does not establish any compromise of a signing key.','การเปรียบเทียบนี้ไม่ได้พิสูจน์ว่า Signing Key ถูกยึดครอง'],
['SHA-256 has produced a collision for these two files','SHA-256 เกิด Collision สำหรับไฟล์สองชุดนี้','A collision would involve equal digests for different inputs; this observation is unequal digests.','Collision คือข้อมูลต่างกันให้ Digest เท่ากัน แต่สิ่งที่พบคือ Digest ไม่เท่ากัน']], 'Bound an integrity inference to what a trusted mismatch establishes')
add(1009,'What is the purpose of post-quantum cryptography in protecting organizational systems?','Post-quantum cryptography มีวัตถุประสงค์ใดในการปกป้องระบบขององค์กร?',[
['Use cryptographic methods designed to resist quantum-capable attacks','ใช้วิธี Cryptography ที่ออกแบบให้ต้านทานการโจมตีด้วยคอมพิวเตอร์ควอนตัม','PQC addresses quantum threats through resistant cryptographic schemes, including key establishment and signatures.','PQC รับมือภัยควอนตัมด้วยกลไกที่ต้านทาน เช่น การสร้างกุญแจร่วมและลายเซ็น'],
['Replace conventional computers with quantum computers for encryption','เปลี่ยนคอมพิวเตอร์ปกติเป็นคอมพิวเตอร์ควอนตัมเพื่อเข้ารหัส','PQC schemes can run on conventional computers; quantum hardware is not their defining requirement.','กลไก PQC ทำงานบนคอมพิวเตอร์ปกติได้ ไม่ได้กำหนดว่าต้องใช้ฮาร์ดแวร์ควอนตัม'],
['Require quantum communication channels for every encrypted session','กำหนดให้ทุก Session ที่เข้ารหัสใช้ช่องสื่อสารควอนตัม','Quantum communication is distinct from post-quantum algorithms used on ordinary systems.','การสื่อสารควอนตัมต่างจากอัลกอริทึม Post-quantum ที่ใช้บนระบบทั่วไป'],
['Remove the need to manage cryptographic keys during migration','ยกเลิกความจำเป็นในการจัดการกุญแจระหว่างการย้ายระบบ','Resistant algorithms still depend on appropriate key management and deployment.','อัลกอริทึมที่ต้านทานยังต้องอาศัยการจัดการกุญแจและการติดตั้งที่เหมาะสม']], 'Recognize the purpose of PQC without quantum-hardware confusion')
add(1010,'A company stores records that must remain confidential for many years. Its bulk encryption uses AES, but its key-establishment process uses a quantum-vulnerable public-key scheme. What should its migration assessment include?','บริษัทเก็บบันทึกที่ต้องเป็นความลับอีกหลายปี โดยเข้ารหัสข้อมูลจำนวนมากด้วย AES แต่กระบวนการสร้างกุญแจใช้ Public-key scheme ที่เสี่ยงต่อควอนตัม การประเมินการย้ายระบบควรรวมอะไร?',[
['Identify the vulnerable key-establishment dependency and assess approved replacements','ระบุส่วนสร้างกุญแจที่มีความเสี่ยงและประเมินวิธีทดแทนที่อนุมัติ','The public-key dependency remains relevant even when bulk data uses a symmetric cipher.','ส่วน Public-key ยังต้องได้รับการประเมินแม้ข้อมูลจำนวนมากใช้ Symmetric cipher'],
['Treat the use of AES as evidence that the whole system is quantum-resistant','ถือว่าการใช้ AES พิสูจน์ว่าระบบทั้งหมดต้านทานควอนตัมแล้ว','The bulk cipher does not establish resistance of the separate key-establishment mechanism.','อัลกอริทึมเข้ารหัสข้อมูลไม่ได้พิสูจน์ความต้านทานของกลไกสร้างกุญแจที่แยกกัน'],
['Replace the bulk cipher while keeping the vulnerable public-key process','เปลี่ยนตัวเข้ารหัสข้อมูลโดยคงกระบวนการ Public-key ที่มีความเสี่ยง','Changing only bulk encryption leaves the identified vulnerable dependency unaddressed.','การเปลี่ยนเฉพาะการเข้ารหัสข้อมูลยังไม่จัดการส่วนที่ระบุว่ามีความเสี่ยง'],
['Limit the review to whether the existing keys are stored securely','จำกัดการทบทวนเฉพาะการเก็บกุญแจเดิมว่าปลอดภัยหรือไม่','Secure storage matters, but does not remove the algorithmic quantum vulnerability described.','การเก็บอย่างปลอดภัยสำคัญ แต่ไม่ลบความเสี่ยงควอนตัมของอัลกอริทึมที่โจทย์ระบุ']], 'Assess vulnerable key dependencies despite protected bulk data')
(p/'draft-batch-1.json').write_text(json.dumps(items,ensure_ascii=False,indent=2),encoding='utf-8')
print('Authored batch1:',len(items))
